<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); ?>
<section class="portal-page-heading"><p class="eyebrow"><?= $e($championship['name']) ?></p><h1><?php $titles = ['next' => 'Proximos jogos', 'results' => 'Resultados', 'standings' => 'Classificacao', 'groups' => 'Grupos', 'knockout' => 'Mata-mata', 'teams' => 'Equipes', 'athletes' => 'Atletas', 'goals' => 'Artilharia', 'assists' => 'Assistencias', 'cards' => 'Cartoes', 'regulation' => 'Regulamento', 'champion' => 'Campeao e vice']; echo $e($titles[$kind] ?? $kind); ?></h1><p>Informacoes publicadas e verificadas pela organizacao.</p></section>
<?php if (in_array($kind, ['teams', 'athletes'], true)): ?><form class="portal-search" method="get"><label>Buscar <input name="q" value="<?= $e($search ?? '') ?>"></label><button type="submit">Buscar</button></form><?php endif; ?>
<?php if ($kind === 'next'): ?><div class="match-cards match-cards-large"><?php foreach ($items as $match): ?><a class="match-card" href="<?= $e($base . '/partidas/' . $match['id']) ?>"><span><?= $e($match['match_date'] ?: 'A definir') ?> <?= $e(substr((string) ($match['match_time'] ?: ''), 0, 5)) ?></span><strong><?= $e($match['home_team_name']) ?> <b>×</b> <?= $e($match['away_team_name']) ?></strong><small><?= $e($match['venue_name'] ?: $match['phase_name']) ?> · <?= $e($match['group_name']) ?></small></a><?php endforeach; ?></div><?php elseif ($kind === 'results'): ?><div class="result-list result-list-large"><?php foreach ($items as $match): ?><a href="<?= $e($base . '/partidas/' . $match['id']) ?>"><span><?= $e($match['home_team_name']) ?></span><strong><?= (int) $match['home_score'] ?> × <?= (int) $match['away_score'] ?></strong><span><?= $e($match['away_team_name']) ?></span><small><?= $e($match['match_date']) ?></small></a><?php endforeach; ?></div><?php elseif ($kind === 'standings'): ?><?php $group = ''; foreach ($items as $row): if ($group !== $row['group_name']): if ($group !== ''): ?></tbody></table></div><?php endif; $group = $row['group_name']; ?><div class="portal-table-block"><h2><?= $e($row['phase_name']) ?> · <?= $e($group) ?></h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Equipe</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th><th>Pts</th></tr></thead><tbody><?php endif; ?><tr><td><?= (int) $row['position'] ?></td><td><a href="<?= $e($base . '/equipes/' . rawurlencode($row['slug'])) ?>"><?= $e($row['team_name']) ?></a></td><td><?= (int) $row['matches_played'] ?></td><td><?= (int) $row['wins'] ?></td><td><?= (int) $row['draws'] ?></td><td><?= (int) $row['losses'] ?></td><td><?= (int) $row['goals_for'] ?></td><td><?= (int) $row['goals_against'] ?></td><td><?= (int) $row['goal_difference'] ?></td><td><strong><?= (int) $row['points'] ?></strong></td></tr><?php endforeach; if ($group !== ''): ?></tbody></table></div></div><?php endif; ?><?php elseif ($kind === 'groups'): ?><?php foreach ($items as $group): ?><section class="portal-card"><h2><?= $e($group['phase_name']) ?> · <?= $e($group['name']) ?></h2><p>Classificam <?= (int) $group['qualified_limit'] ?> equipes.</p><ol><?php foreach ($group['teams'] as $team): ?><li><a href="<?= $e($base . '/equipes/' . rawurlencode($team['slug'])) ?>"><?= $e($team['name']) ?></a></li><?php endforeach; ?></ol></section><?php endforeach; ?><?php elseif ($kind === 'knockout'): ?><div class="knockout-grid"><?php foreach ($items as $tie): ?><article class="knockout-tie"><p class="eyebrow"><?= $e($tie['stage']) ?> · confronto <?= (int) $tie['tie_number'] ?></p><strong><?= $e($tie['home_team_name'] ?: $tie['home_source']) ?></strong><span>×</span><strong><?= $e($tie['away_team_name'] ?: $tie['away_source']) ?></strong><small><?= $e($tie['winner_team_name'] ? 'Vencedor: ' . $tie['winner_team_name'] : 'A definir') ?></small><?php if ($tie['match_id']): ?><a href="<?= $e($base . '/partidas/' . $tie['match_id']) ?>">Detalhes da partida</a><?php endif; ?></article><?php endforeach; ?></div><?php elseif ($kind === 'teams'): ?><div class="portal-card-grid"><?php foreach ($items as $team): ?><a class="portal-card" href="<?= $e($base . '/equipes/' . rawurlencode($team['slug'])) ?>"><?php if ($team['shield_path']): ?><img class="portal-shield" src="<?= $e($base . '/equipes/' . rawurlencode($team['slug']) . '/escudo') ?>" alt="Escudo de <?= $e($team['name']) ?>"><?php endif; ?><h2><?= $e($team['name']) ?></h2><p><?= $e($team['city'] ?: $team['abbreviation']) ?></p></a><?php endforeach; ?></div><?php elseif ($kind === 'athletes'): ?><div class="portal-card-grid"><?php foreach ($items as $athlete): ?><a class="portal-card" href="<?= $e($base . '/atletas/' . $athlete['id']) ?>"><?php if ($athlete['photo_path']): ?><img class="portal-athlete-photo" src="<?= $e($base . '/atletas/' . $athlete['id'] . '/foto') ?>" alt="Foto de <?= $e($athlete['athlete_name'] ?? $athlete['full_name']) ?>"><?php endif; ?><h2><?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?></h2><p><?= $e($athlete['position_name']) ?> · <?= $e($athlete['team_name']) ?></p></a><?php endforeach; ?></div><?php elseif (in_array($kind, ['goals', 'assists'], true)): ?><div class="ranking-table"><table><thead><tr><th>#</th><th>Atleta</th><th>Equipe</th><th>Total</th></tr></thead><tbody><?php foreach ($items as $index => $row): ?><tr><td><?= $index + 1 ?></td><td><a href="<?= $e($base . '/atletas/' . $row['athlete_id']) ?>"><?= $e($row['sporting_name'] ?: $row['full_name']) ?></a></td><td><?= $e($row['team_name']) ?></td><td><strong><?= (int) $row['total'] ?></strong></td></tr><?php endforeach; ?></tbody></table></div><?php elseif ($kind === 'cards'): ?><div class="ranking-table"><table><thead><tr><th>Atleta</th><th>Equipe</th><th>Amarelos</th><th>Vermelhos</th></tr></thead><tbody><?php foreach ($items as $row): ?><tr><td><?= $e($row['sporting_name'] ?: $row['full_name']) ?></td><td><?= $e($row['team_name']) ?></td><td><?= (int) $row['yellows'] ?></td><td><?= (int) $row['reds'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php elseif ($kind === 'regulation'): ?><?php if ($items): ?><dl class="portal-definition"><dt>Documento</dt><dd><?= $e($items['name']) ?> · versao <?= (int) $items['version_number'] ?></dd><dt>Vigencia</dt><dd><?= $e($items['effective_from'] ?: '-') ?></dd><dt>Pontuacao</dt><dd>Vitoria <?= (int) $items['points_win'] ?> · empate <?= (int) $items['points_draw'] ?> · derrota <?= (int) $items['points_loss'] ?></dd><dt>Classificados por grupo</dt><dd><?= (int) $items['qualified_per_group'] ?></dd><dt>Tempo extra</dt><dd><?= !empty($items['extra_time_enabled']) ? 'Permitido' : 'Nao previsto' ?></dd><dt>Penaltis</dt><dd><?= !empty($items['penalty_shootout_enabled']) ? 'Permitidos' : 'Nao previstos' ?></dd></dl><?php else: ?><p>Regulamento publicado ainda nao disponivel.</p><?php endif; ?><?php elseif ($kind === 'champion'): ?><?php if ($items): ?><div class="champion-grid"><article><p class="eyebrow">Campeao</p><?php if ($items['champion_shield_path']): ?><img class="portal-shield" src="<?= $e($base . '/equipes/' . rawurlencode($items['champion_slug']) . '/escudo') ?>" alt="Escudo do campeao"><?php endif; ?><h2><?= $e($items['champion_name']) ?></h2></article><article><p class="eyebrow">Vice-campeao</p><h2><?= $e($items['runner_up_name'] ?: 'A definir') ?></h2></article></div><?php else: ?><p>Campeao e vice ainda nao definidos.</p><?php endif; ?><?php else: ?><p>Nenhum dado publicado.</p><?php endif; ?>
